{"command":"python3 - <<'PY'
import sys; sys.path.insert(0,'/tmp')
from run_tmux import capture
from collections import Counter, defaultdict
pairs=Counter()
first_to_seconds=defaultdict(Counter)
seconds_to_first=defaultdict(Counter)
for run in range(3):
    res=capture(["-c"], wait=0.8)
    for line in res['cap'].splitlines():
        # pad to 80
        line=line.ljust(80)
        for k in range(40):
            a=line[2*k]; b=line[2*k+1]
            pairs[(a,b)]+=1
            if a!=' ':
                first_to_seconds[a][b]+=1
            if b!=' ':
                seconds_to_first[b][a]+=1
# print first mapping
print("FIRST -> SECONDS")
for a in sorted(first_to_seconds, key=lambda c: ord(c)):
    print(f"{a!r} U+{ord(a):04X} -> {dict(first_to_seconds[a])}")
print("\nSECOND distinct counts")
for b in sorted(seconds_to_first, key=lambda c: ord(c)):
    print(f"{b!r} {ord(b)} <- {dict(seconds_to_first[b])} ")
PY"}

