import re
def parse_grid(cape):
    rows=[]; row=[]
    fg=None; bold=False
    i=0
    while i<len(cape):
        if cape[i]=='\x1b':
            m=re.match(r'\x1b\[([0-9;]*)m', cape[i:])
            if m:
                code=m.group(1)
                if code in ('0',''):
                    fg=None; bold=False
                elif code=='1':
                    bold=True
                elif code=='22':
                    bold=False
                elif code=='39':
                    fg=None
                elif code=='49':
                    pass
                elif ';' in code:
                    parts=code.split(';')
                    for p in parts:
                        if p=='39': fg=None
                        elif p=='1': bold=True
                        elif p=='0': fg=None; bold=False
                        elif p.isdigit() and 30<=int(p)<=37: fg=p
                elif code.isdigit() and 30<=int(code)<=37:
                    fg=code
                i+=len(m.group(0)); continue
            m2=re.match(r'\x1b\[[0-9;]*[A-Za-z]', cape[i:])
            if m2:
                i+=len(m2.group(0)); continue
            i+=1; continue
        elif cape[i]=='\n':
            rows.append(row); row=[]; fg=None; bold=False; i+=1
        else:
            row.append((cape[i], fg, bold)); i+=1
    if row: rows.append(row)
    return rows
