/*
 * A Matrix-like terminal screensaver.
 *
 * This is an independent implementation of the observable behaviour of
 * the CMatrix program: columns of characters grow, travel and fade down
 * the terminal, with a bright leading character.
 */

#define _XOPEN_SOURCE 700
#define _DEFAULT_SOURCE 1

#include <ctype.h>
#include <errno.h>
#include <locale.h>
#include <ncursesw/ncurses.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <time.h>
#include <unistd.h>
#include <wchar.h>

/* ------------------------------------------------------------------ */
/* Command line state                                                  */

static bool opt_async;
static int  opt_bold;          /* 0 none, 1 parity, 2 all, -1 cmdline -n */
static bool opt_force;
static bool opt_japanese;
static bool opt_change;        /* -k */
