static bool opt_paused;
static int  opt_update = 4;
static short matrix_color = COLOR_GREEN;
static const char *opt_message;
static const char *opt_tty;

static volatile sig_atomic_t need_resize;

static void usage(void)
{
    fputs(
" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n"
" -a: Asynchronous scroll\n"
" -b: Bold characters on\n"
" -B: All bold characters (overrides -b)\n"
" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n"
" -f: Force the linux $TERM type to be on\n"
" -l: Linux mode (uses matrix console font)\n"
" -L: Lock mode (can be closed from another terminal)\n"
" -o: Use old-style scrolling\n"
" -h: Print usage and exit\n"
" -n: No bold characters (overrides -b and -B, default)\n"
" -s: \"Screensaver\" mode, exits on first keystroke\n"
" -x: X window mode, use if your xterm is using mtx.pcf\n"
" -V: Print version information and exit\n"
" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n"
" -u delay (0 - 10, default 4): Screen update delay\n"
" -C [color]: Use this color for matrix (default green)\n"
" -r: rainbow mode\n"
" -m: lambda mode\n"
" -k: Characters change while scrolling. (Works without -o opt.)\n"
" -t [tty]: Set tty to use\n",
        stdout);
}

static void version(void)
{
    printf(" CMatrix version 2.0 (compiled %s, %s)\n", __TIME__, __DATE__);
    printf("Email: abishekvashok@gmail.com\n");
    printf("Web: https://github.com/abishekvashok/cmatrix\n");
}

/* ------------------------------------------------------------------ */
/* Screen / stream state                                               */

enum cell_kind {
    CELL_BLANK = 0,
    CELL_CHAR,       /* an ordinary falling character */
    CELL_HEAD,       /* new-style leading character */
    CELL_OLD_HEAD,   /* old-style '&' sentinel */
    CELL_OLD_PIPE    /* old-style '|' sentinel */
};

typedef struct {
    int val;
    int kind;
} Cell;

typedef struct {
    bool active;
    bool adding;     /* still extending toward the bottom */
    int top;
    int head;
    int length;
} Stream;

#define MAX_STREAMS_PER_COLUMN 4

typedef struct {
    /* common / new style */
    int spaces;
    int next_length;
    int updates;     /* 1..3: updates per three ticks in async mode */
    Stream streams[MAX_STREAMS_PER_COLUMN];

    /* old style */
    bool old_emitting;
    bool old_head_run;
    int old_remaining;
    int old_emit_count;
} Column;

static Cell **matrix;
static Column *columns;
static int term_lines;
static int term_cols;      /* physical terminal columns */
static int nlines;         /* matrix rows (cached at startup) */
static int ncols;          /* matrix columns, printed every other column */
static long tick_count;

static void finish(int status)
{
    curs_set(1);
    clear();
    refresh();
    endwin();
    exit(status);
}

static void signal_finish(int sig)
{
    (void)sig;
    finish(0);
}

static void signal_resize(int sig)
{
    (void)sig;
    need_resize = 1;
}

static int random_length(void)
{
    /* Kept in this form deliberately: it is the historical formula. */
    return rand() % (nlines - 3) + 3;
}

static int random_char(void)
{
    if (opt_japanese)
        return 65382 + rand() % 55;      /* U+FF66 .. U+FF9C */
    if (opt_xwindow)
        return 166 + rand() % 51;        /* mtx.pcf glyph range */
    return 33 + rand() % 90;             /* '!' .. 'z' */
}

static void matrix_init(void)
{
    nlines = term_lines;
    ncols = (term_cols + 1) / 2;

    matrix = calloc((size_t)(nlines > 0 ? nlines : 1), sizeof(*matrix));
    if (matrix != NULL) {
        for (int i = 0; i < nlines; i++)
            matrix[i] = calloc((size_t)(ncols > 0 ? ncols : 1),
                                 sizeof(**matrix));
    }

    columns = calloc((size_t)(ncols > 0 ? ncols : 1), sizeof(*columns));
    if (columns == NULL)
        return;

    for (int j = 0; j < ncols; j++) {
        Column *col = &columns[j];
        col->next_length = random_length();
        col->spaces = (nlines > 0) ? rand() % nlines + 1 : 1;
        col->updates = rand() % 3 + 1;

        /* Old style starts in a gap of a random length.  A zero
         * remaining count is represented by starting to emit. */
        col->old_remaining = (nlines > 0) ? rand() % (nlines + 1) : 0;
        col->old_emitting = (col->old_remaining == 0);
        col->old_head_run = (rand() % 3 == 0);
        col->old_emit_count = 0;
    }
}

/* ------------------------------------------------------------------ */
/* New-style stream updates                                            */

static Stream *find_stream_slot(Column *col)
{
    for (int i = 0; i < MAX_STREAMS_PER_COLUMN; i++)
        if (!col->streams[i].active)
            return &col->streams[i];
    return NULL;
}

static void spawn_stream(Column *col, int j)
{
    Stream *st = find_stream_slot(col);
    if (st == NULL || nlines <= 0)
        return;

    st->active = true;
    st->adding = true;
    st->top = 0;
    st->head = 0;
    st->length = col->next_length;

    matrix[0][j].val = random_char();
    matrix[0][j].kind = CELL_HEAD;

    if (st->head == nlines - 1) {
        /* A one-line terminal: the head is already at the bottom. */
        st->adding = false;
        col->spaces = (nlines > 0) ? rand() % nlines + 1 : 1;
        col->next_length = random_length();
    }
}

static void update_new_column(int j)
{
    Column *col = &columns[j];
    bool has_adding = false;

    /* -k: occasionally replace an existing character. */
    if (opt_change) {
        for (int i = 0; i < nlines; i++) {
            if (matrix[i][j].kind == CELL_CHAR ||
                matrix[i][j].kind == CELL_HEAD) {
                if (rand() % 8 == 0)
                    matrix[i][j].val = random_char();
            }
        }
    }

    for (int s = 0; s < MAX_STREAMS_PER_COLUMN; s++) {
        Stream *st = &col->streams[s];
        if (!st->active)
            continue;

        if (st->adding) {
            has_adding = true;

            if (st->head >= nlines - 1) {
                /* Should have been marked finished when the bottom
                 * character was added, but be defensive. */
                st->adding = false;
                continue;
            }

            /* The old head becomes part of the trail and a new head
             * appears immediately beneath it.  Characters themselves
             * never move in new-style mode. */
            if (matrix[st->head][j].kind == CELL_HEAD)
                matrix[st->head][j].kind = CELL_CHAR;

            st->head++;
            matrix[st->head][j].val = random_char();
            matrix[st->head][j].kind = CELL_HEAD;

            if (st->head - st->top + 1 > st->length) {
                matrix[st->top][j].val = 0;
                matrix[st->top][j].kind = CELL_BLANK;
                st->top++;
            }

            if (st->head >= nlines - 1) {
                /* Let the tail expire on later updates while the
                 * column scheduler counts down to the next stream. */
                st->adding = false;
                has_adding = false;
                col->spaces = (nlines > 0) ? rand() % nlines + 1 : 1;
                col->next_length = random_length();
            }
        } else {
            /* Expiring: erase from the tail, one cell per update. */
            if (st->top <= st->head && st->top < nlines) {
                matrix[st->top][j].val = 0;
                matrix[st->top][j].kind = CELL_BLANK;
                st->top++;
            }
            if (st->top > st->head)
                st->active = false;
        }
    }

    if (!has_adding) {
        if (col->spaces > 0) {
            col->spaces--;
        } else {
            spawn_stream(col, j);
        }
    }
}

/* ------------------------------------------------------------------ */
/* Old-style stream updates                                            */

static Cell old_next_top_cell(Column *col)
{
    Cell cell;
    cell.val = 0;
    cell.kind = CELL_BLANK;

    if (!col->old_emitting) {
        if (col->old_remaining > 0)
            col->old_remaining--;
        if (col->old_remaining <= 0) {
            col->old_emitting = true;
            col->old_head_run = (rand() % 3 == 0);
            col->old_emit_count = 0;
        }
        return cell;
    }

    if (col->old_head_run && col->old_emit_count == 0) {
        cell.kind = CELL_OLD_HEAD;
        cell.val = '&';
    } else if (col->old_head_run && col->old_emit_count == 1) {
        cell.kind = CELL_OLD_PIPE;
        cell.val = '|';
    } else {
        cell.kind = CELL_CHAR;
        cell.val = random_char();
    }
    col->old_emit_count++;

    /* End the run with a roughly constant per-frame probability,
     * after the minimum '&' / '|' / character sequence for a
     * headed run.  This reproduces the long-tailed run lengths
     * seen in old-style mode. */
    int minimum = col->old_head_run ? 3 : 1;
    if (col->old_emit_count >= minimum && rand() % 14 == 0) {
        col->old_emitting = false;
        col->old_remaining = (nlines > 0) ? rand() % nlines + 2 : 2;
        col->old_emit_count = 0;
    }

    return cell;
}

static void update_old(void)
{
    if (nlines <= 0 || ncols <= 0)
        return;

    /* Everything already on the screen moves down one row. */
    for (int i = nlines - 1; i > 0; i--)
        for (int j = 0; j < ncols; j++)
            matrix[i][j] = matrix[i - 1][j];

    for (int j = 0; j < ncols; j++)
        matrix[0][j] = old_next_top_cell(&columns[j]);
}

static void update_matrix(void)
{
    if (matrix == NULL || columns == NULL)
        return;

    if (opt_oldstyle) {
        update_old();
        tick_count++;
        return;
    }

    int phase = (int)(tick_count % 3);
    for (int j = 0; j < ncols; j++) {
        if (!opt_async || columns[j].updates > phase)
            update_new_column(j);
    }
    tick_count++;
}

/* ------------------------------------------------------------------ */
/* Drawing                                                             */

static short rainbow_pair(void)
{
    /* Pair numbers are also colour numbers below.  The six outcomes
     * deliberately include pair 0 (the default pair). */
    static const short choices[6] = {
        COLOR_BLACK, COLOR_GREEN, COLOR_YELLOW,
        COLOR_BLUE, COLOR_MAGENTA, COLOR_CYAN
    };
    return choices[rand() % 6];
}

static void set_attrs(short pair, bool bold)
{
    attr_t attrs = A_NORMAL;
    if (bold)
        attrs |= A_BOLD;
    attrset(attrs | COLOR_PAIR(pair));
}

static bool trail_bold(int val)
{
    return opt_bold == 2 || (opt_bold == 1 && val % 2 == 0);
}

static void draw_wide(int y, int x, int val)
{
    wchar_t text[2];
    text[0] = (wchar_t)val;
    text[1] = L'\0';
    mvwaddwstr(stdscr, y, x, text);
}

static int displayed_char(int val)
{
    if (opt_lambda)
        return 0x03bb;   /* Greek small letter lambda */
    return val;
}

static void draw_screen(void)
{
    bool show_message = false;
    size_t message_len = 0;
    int message_x = 0;
    int message_y = term_lines / 2;

    if (opt_message != NULL) {
        message_len = strlen(opt_message);
        if (message_len > 0 && (int)message_len < term_cols - 2) {
            show_message = true;
            message_x = term_cols / 2 - (int)(message_len / 2);
        }
    }

    for (int i = 0; i < nlines; i++) {
        for (int j = 0; j < ncols; j++) {
            int x = j * 2;
            Cell *cell = &matrix[i][j];

            if (show_message && i >= message_y - 1 && i <= message_y + 1 &&
                x >= message_x - 2 && x < message_x + (int)message_len + 2) {
                attrset(A_NORMAL);
                mvaddch(i, x, ' ');
                continue;
            }

            if (cell->kind == CELL_BLANK) {
                short pair = opt_rainbow ? rainbow_pair() : matrix_color;
                set_attrs(pair, opt_bold == 2);
                mvaddch(i, x, ' ');
                continue;
            }

            if (opt_rainbow && !opt_oldstyle) {
                int val = (cell->kind == CELL_OLD_PIPE) ? '|' : cell->val;
                set_attrs(rainbow_pair(), trail_bold(val));
                draw_wide(i, x, displayed_char(val));
                continue;
            }

            if (cell->kind == CELL_HEAD) {
                set_attrs((short)COLOR_WHITE, opt_bold != 0);
                {
                    chtype ch = (chtype)cell->val;
                    if (opt_xwindow)
                        ch |= A_ALTCHARSET;
                    mvwaddch(stdscr, i, x, ch);
                }
                continue;
            }

            if (cell->kind == CELL_OLD_HEAD) {
                set_attrs((short)COLOR_WHITE, opt_bold != 0);
                if (opt_xwindow) {
                    mvwaddch(stdscr, i, x,
                             (chtype)166 | A_ALTCHARSET);
                } else {
                    mvaddch(i, x, '&');
                }
                continue;
            }

            if (cell->kind == CELL_OLD_PIPE) {
                short pair = opt_rainbow ? rainbow_pair() : matrix_color;
                bool bold = opt_rainbow ? trail_bold('|') : (opt_bold != 0);
                set_attrs(pair, bold);
                mvaddch(i, x, '|');
                continue;
            }

            /* Ordinary trail characters (and old-style randoms). */
            {
                short pair = opt_rainbow ? rainbow_pair() : matrix_color;
                set_attrs(pair, trail_bold(cell->val));
                draw_wide(i, x, displayed_char(cell->val));
            }
        }
    }

    if (show_message) {
        attrset(A_NORMAL);
        mvaddstr(message_y, message_x, opt_message);
    }

    refresh();
}

/* ------------------------------------------------------------------ */

static void handle_key(int key)
{
    switch (key) {
    case 'q':
        if (!opt_lock)
            finish(0);
        break;
    case 'a':
        opt_async = !opt_async;
        break;
    case 'b':
        opt_bold = 1;
        break;
    case 'B':
        opt_bold = 2;
        break;
    case 'n':
        opt_bold = 0;
        break;
    case 'm':
        opt_lambda = !opt_lambda;
        break;
    case 'p':
    case 'P':
        opt_paused = !opt_paused;
        break;
    case 'r':
        opt_rainbow = true;
        break;
    case '!':
        matrix_color = COLOR_RED;
        opt_rainbow = false;
        break;
    case '@':
        matrix_color = COLOR_GREEN;
        opt_rainbow = false;
        break;
    case '#':
        matrix_color = COLOR_YELLOW;
        opt_rainbow = false;
        break;
    case '$':
        matrix_color = COLOR_BLUE;
        opt_rainbow = false;
        break;
    case '%':
        matrix_color = COLOR_MAGENTA;
        opt_rainbow = false;
        break;
    case '^':
        matrix_color = COLOR_CYAN;
        opt_rainbow = false;
        break;
    case '&':
        matrix_color = COLOR_WHITE;
        opt_rainbow = false;
        break;
    default:
        if (key >= '0' && key <= '9')
            opt_update = key - '0';
        break;
    }
}

static short parse_color(const char *text)
{
    struct { const char *name; short value; } const colors[] = {
        { "black", COLOR_BLACK }, { "red", COLOR_RED },
        { "green", COLOR_GREEN }, { "yellow", COLOR_YELLOW },
        { "blue", COLOR_BLUE },   { "magenta", COLOR_MAGENTA },
        { "cyan", COLOR_CYAN },   { "white", COLOR_WHITE },
    };

    for (size_t i = 0; i < sizeof(colors) / sizeof(colors[0]); i++) {
        if (strcasecmp(text, colors[i].name) == 0)
            return colors[i].value;
    }

    fprintf(stderr, " Invalid color selection\n");
    fprintf(stderr,
            " Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
    exit(0);
}

int main(int argc, char **argv)
{
    int option_char;

    opterr = 0;
    while ((option_char = getopt(argc, argv,
                                  "abBcC:fhklLM:mnorst:u:Vx")) != -1) {
        switch (option_char) {
        case 'a':
            opt_async = true;
            break;
        case 'b':
            if (opt_bold != 2)
                opt_bold = 1;
            break;
        case 'B':
            opt_bold = 2;
            break;
        case 'c':
            opt_japanese = true;
            break;
        case 'C':
            matrix_color = parse_color(optarg);
            break;
        case 'f':
            opt_force = true;
            break;
        case 'h':
            usage();
            return 0;
        case 'k':
            opt_change = true;
            break;
        case 'l':
            opt_linuxfont = true;
            break;
        case 'L':
            opt_lock = true;
            if (opt_message == NULL || opt_message[0] == '\0')
                opt_message = "Computer locked.";
            break;
        case 'M':
            opt_message = optarg;
            break;
        case 'm':
            opt_lambda = true;
            break;
        case 'n':
            opt_bold = -1;
            break;
        case 'o':
            opt_oldstyle = true;
            break;
        case 'r':
            opt_rainbow = true;
            break;
        case 's':
            opt_screensaver = true;
            break;
        case 't':
            opt_tty = optarg;
            break;
        case 'u':
            opt_update = atoi(optarg);
            break;
        case 'V':
            version();
            return 0;
        case 'x':
            opt_xwindow = true;
            break;
        default:
            usage();
            return 0;
        }
    }

    setlocale(LC_ALL, "");

    if (opt_force) {
        if (strcmp(getenv("TERM"), "linux") != 0)
            putenv((char *)"TERM=linux");
    }

    FILE *tty_file = NULL;
    if (opt_tty != NULL) {
        tty_file = fopen(opt_tty, "r+");
        if (tty_file == NULL) {
            int saved_errno = errno;
            fprintf(stderr, "cmatrix: error: '%s' couldn't be opened: %s.\n",
                    opt_tty, strerror(saved_errno));
            return 1;
        }
    }

    if (tty_file != NULL) {
        SCREEN *screen = newterm(NULL, tty_file, tty_file);
        if (screen == NULL)
            return 1;
        set_term(screen);
    } else {
        initscr();
    }

    cbreak();
    noecho();
    nodelay(stdscr, TRUE);
    curs_set(0);

    if (has_colors()) {
        start_color();
        use_default_colors();
        for (short i = 0; i < 8; i++)
            init_pair(i, i, -1);
    }

    signal(SIGINT, signal_finish);
    signal(SIGQUIT, signal_finish);
    signal(SIGTSTP, signal_finish);
    signal(SIGWINCH, signal_resize);

    srand((unsigned int)(time(NULL) * getpid()));

    term_lines = LINES;
    term_cols = COLS;
    matrix_init();

    if (opt_linuxfont) {
        /* No usable console-font loader is compiled into this build
         * (the historical setfont / consolechars alternatives). */
        endwin();
        fprintf(stderr,
                " Unable to use both \"setfont\" and \"consolechars\".\n");
        return 0;
    }

    for (;;) {
        if (need_resize) {
            need_resize = 0;
            endwin();
            refresh();
            clear();
        }

        int key = getch();
        if (opt_screensaver) {
            if (key != ERR && key != KEY_RESIZE)
                finish(0);
        } else if (key != ERR && key != KEY_RESIZE) {
            handle_key(key);
        }

        if (!opt_paused)
            update_matrix();

        draw_screen();
        napms(opt_update * 10);
    }

    return 0;
}
