static bool opt_paused;
static int  opt_update = 4;
static short matrix_color = COLOR_GREEN;
static const char *opt_message;
static const char *opt_tty;

static volatile sig_atomic_t need_resize;

static void usage(void)
{
    fputs(
" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n"
" -a: Asynchronous scroll\n"
