set -e
cd "$(dirname "$0")"
CC="${CC:-cc}"
if ! "$CC" -O2 -o executable cmatrix.c -lncursesw 2>/dev/null; then
    # Try to obtain the wide-character ncurses development files if
    # this is a system on which a package manager is available.
    if command -v apt-get >/dev/null 2>&1; then
        apt-get update && apt-get install -y gcc libncurses-dev
    fi
    "$CC" -O2 -o executable cmatrix.c -lncursesw
fi
EOS
