{"command":"cat > /tmp/ptyrate.py <<'PY'
import subprocess,os,time,select
def measure(exe,args):
 p=subprocess.Popen([exe]+args,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,env={**os.environ,'TERM':'xterm'})
 os.set_blocking(p.stdout.fileno(),False)
 chunks=[];st=time.time();total=0
 while time.time()-st<4:
  r,_,_=select.select([p.stdout],[],[],.01)
  if r:
   data=os.read(p.stdout.fileno(),65536)
   if data:chunks.append((time.time()-st,len(data)));total+=len(data)
 p.stdin.write(b'q');p.stdin.flush()
 try:p.wait(timeout=1)
 except:p.kill()
 # group chunks separated >10ms as bursts
 bursts=[]
 for t,n in chunks:
  if not bursts or t-bursts[-1][-1][0]>.01:bursts.append([(t,n)])
  else:bursts[-1].append((t,n))
 times=[b[0][0] for b in bursts]
 intervals=[round((b-a)*1000,1) for a,b in zip(times,times[1:])]
 from collections import Counter
 print(exe,args,'totalbytes',total,'bursts',len(bursts),'first times',[round(x,3) for x in times[:15]],'intervals sample',intervals[:20],'median interval',sorted(intervals)[len(intervals)//2] if intervals else None)
for args in [[],["-a"],["-u","10"],["-u","10","-a"]]:
 measure('/tmp/ref_executable',args);measure('./executable',args)
